  ($str$bar_tube_fab_band_saw$str$, NULL::text, 'India', 'IN', $str$bar_tube_fab_2_roll_bending$str$, $str$Acrotec LD-1230$str$, 2.3, 2.05, 0.95, $str$2 Roll Bending:Acrotec LD-1230:India$str$, NULL::numeric, NULL::integer, NULL::integer, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, NULL::numeric, NULL::jsonb),
