    n := n + 1;
  END LOOP;

  RAISE NOTICE 'Bar and Tube Fabrication rows inserted: %', n;
  IF array_length(missing, 1) > 0 THEN
    RAISE NOTICE 'Bar and Tube Fabrication rows with no USA source row (not inserted): %', missing;
  END IF;
END $bar_tube_machines$;

